state.src:
function () {
                const tiers = [];
                for (const held of masked) {
                    for (const tile of (held.surface.tiles || [])) {
                        tiers.push(tile.tier);
                    }
                }
                tiers.sort(function (a, b) { return a - b; });
                return "[state] applied=" + maskState.applied + " lifting=" + maskState.lifting
                    + " tiers=" + (tiers.length ? tiers[0] + ".." + tiers[tiers.length - 1] : "none")
                    + " why=" + maskState.why;
            }

measure.src:
function (longitude, latitude) {
                const carto = Cesium.Cartographic.fromDegrees(longitude, latitude);
                const terrain = globe.getHeight(carto);
                const out = [];
                for (const held of masked) {
                    const surface = held.surface;
                    const lift = liftAt(surface, longitude, latitude);
                    const alpha = maskAt(surface, longitude, latitude);
                    const here = valueAt(surface, longitude, latitude);
                    const clearance = CONFIG.waterMask.clearanceMeters;
                    const lifts = lift.known && alpha !== null && alpha >= 0.5;
                    let sheet = here && here.metres !== undefined ? here.metres : null;
                    if (sheet !== null && lifts) {
                        sheet = Math.max(sheet, lift.value + clearance);
                    }
                    out.push({
                        surface: surface,
                        canLift: lift.known,
                        why: lift.why,
                        terrain: terrain === undefined ? null : terrain,
                        alpha: alpha,
                        lift: lift.known ? lift.value : null,
                        cell: lift.cell,
                        lifted: lifts,
                        value: here && here.metres !== undefined ? here.metres : null,
                        coverage: here ? here.coverage : null,
                        hasData: here ? here.hasData : null,
                        sheet: sheet,
                        margin: sheet === null || terrain === undefined ? null : sheet - terrain,
                        tier: tierAt(surface, longitude, latitude)
                    });
                }
                const lifting = out.filter(function (o) { return o.canLift; });
                return { all: out, chosen: lifting.length ? lifting[0] : out[0] || null };
            }

read.src:
function (longitude, latitude, quiet) {
                const found = handle.measure(longitude, latitude);
                const m = found.chosen;
                if (!m) {
                    return "[at] no masked surface to ask";
                }
                const skipped = found.all.length - 1;
                const text = "[at " + latitude.toFixed(6) + "," + longitude.toFixed(6) + "]"
                    + " tier=" + (m.tier ? m.tier.tier + "(" + Math.round(m.tier.spacing) + "m)" : "?")
                    + " terrain=" + (m.terrain === null ? "?" : m.terrain.toFixed(2))
                    + " inMask=" + (m.alpha === null ? "?"
                        : (m.alpha >= 0.5 ? "yes" : "no") + "(a=" + m.alpha.toFixed(2) + ")")
                    + " held=" + (m.lifted
                        ? "lift " + m.lift.toFixed(2) + " + " + CONFIG.waterMask.clearanceMeters
                            + " = " + (m.lift + CONFIG.waterMask.clearanceMeters).toFixed(2)
                            + " m (cell " + m.cell + ")"
                        : (m.canLift ? "archive value only" : "NO LIFT: " + m.why))
                    + " value=" + (m.value === null ? "?"
                        : m.value.toFixed(2) + "(cov "
                            + (m.coverage === null ? "?" : m.coverage.toFixed(2))
                            + (m.hasData ? "" : " NODATA") + ")")
                    + " sheet=" + (m.sheet === null ? "?" : m.sheet.toFixed(2))
                    + " verdict=" + (m.margin === null ? "?"
                        : (m.margin > 0 ? "WET by " + m.margin.toFixed(2)
                            : "dry by " + (-m.margin).toFixed(2)))
                    + (skipped ? " (+" + skipped + " surface with no lift raster, ignored)" : "");
                if (!quiet) {
                    console.log(text);
                }
                return text;
            }

at.src:
