                return flyTo(longitude, latitude)
                    .then(function () { return settle(SWEEP_SETTLE_MS); })
                    .then(function () { return handle.read(longitude, latitude); });
            }

probe.src:
function (longitude, latitude, metres) {
                const step = metres || 3;
                const dLat = step / 111320;
                const dLon = step / (111320 * Math.cos(latitude * Math.PI / 180));
                const ring = [[longitude, latitude]];
                for (let i = 0; i < 8; i += 1) {
                    const angle = i * Math.PI / 4;
                    ring.push([longitude + Math.sin(angle) * dLon,
                               latitude + Math.cos(angle) * dLat]);
                }
                return flyTo(longitude, latitude)
                    .then(function () { return settle(SWEEP_SETTLE_MS); })
                    .then(function () { return terrainLadder(ring, LADDER_LEVELS); })
